package project

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/edotau/claude-code/internal/textutil"
)

// docsBannerPrefix opens the banner of every generated file; prune/KEEP logic keys on it.
const docsBannerPrefix = "<!-- GENERATED by claude-code agents"

// docsBanner is stamped at the top of every generated agent instruction file.
const docsBanner = docsBannerPrefix + " sync — edit CLAUDE.md + agents/, then re-run. -->"

// docsPathsNote tells a vendor CLI how to resolve the relative paths CLAUDE.md names.
const docsPathsNote = "Paths in this file are relative to `~/.claude`."

// instructionSources are the root instruction files in lookup order: ours, the cross-agent name, then copilot's two.
var instructionSources = []string{"CLAUDE.md", "AGENTS.md",
	filepath.Join(".copilot", "copilot-instructions.md"), filepath.Join(".github", "copilot-instructions.md")}

// instructionSource returns the first instruction file present under root, or fs.ErrNotExist naming CLAUDE.md.
func instructionSource(root string) (string, error) {
	for _, name := range instructionSources {
		p := filepath.Join(root, name)
		if fi, err := os.Stat(p); err == nil && fi.Mode().IsRegular() {
			return p, nil
		}
	}
	return "", &fs.PathError{Op: "stat", Path: filepath.Join(root, instructionSources[0]), Err: fs.ErrNotExist}
}

// PortableCore lists the portable instruction core: the root instruction file, then unscoped rules/standards/*.md.
func PortableCore(root string) ([]string, error) {
	claude, err := instructionSource(root)
	if err != nil {
		return nil, fmt.Errorf("portable core: %w", err)
	}
	standards, err := unscopedStandards(root)
	if err != nil {
		return nil, err
	}
	paths := []string{claude}
	for _, s := range standards {
		paths = append(paths, s.path)
	}
	return paths, nil
}

// externalDrop is a Claude-Code-only `##` section (or intro line prefix) left out of the docs rendered for other CLIs.
type externalDrop struct{ file, heading, linePrefix string }

// externalDrops lists what renderDocs strips; TestExternalDropsMatchRealFiles pins each entry against the real files.
var externalDrops = []externalDrop{
	{file: "CLAUDE.md", heading: "## Where things live"},
	{file: "CLAUDE.md", linePrefix: "3. **Dispatch with the Agent tool.**"},
	{file: "CLAUDE.md", linePrefix: "4. **Tag notable moments**"},
	{file: "CLAUDE.md", linePrefix: "5. **Finish at the requested boundary.**"},
	{file: "CLAUDE.md", heading: "## How-to — by area"},
	{file: "CLAUDE.md", linePrefix: "Injected into **every** session"},
	{file: "CLAUDE.md", linePrefix: "Depth lives elsewhere:"},
	{file: "quality.md", heading: "## Simplify — the gate behind `skills/simplify`"},
	{file: "worktree-git.md", heading: "## Worktrees"},
}

// dropForExternal removes the externalDrops entries for the file at path from body; absent entries are skipped.
func dropForExternal(path, body string) string {
	base := filepath.Base(path)
	lines := strings.Split(body, "\n")
	out := make([]string, 0, len(lines))
	fence, skipLevel, inItem := "", 0, false
	for _, l := range lines {
		t := strings.TrimRight(l, " \t")
		if m := fenceMarker(t); fence == "" {
			fence = m
		} else if m == fence {
			fence = ""
		}
		if fence == "" {
			skipLevel = skipAfter(base, t, skipLevel)
		}
		// a dropped list item takes its indented continuation lines with it
		if inItem && strings.HasPrefix(l, "   ") {
			continue
		}
		inItem = droppedLine(base, t)
		if skipLevel > 0 || inItem {
			continue
		}
		out = append(out, l)
	}
	return strings.Join(out, "\n")
}

// fenceMarker returns the code-fence marker l opens or closes, or "" when l is not a fence line.
func fenceMarker(l string) string {
	for _, m := range []string{"```", "~~~"} {
		if strings.HasPrefix(l, m) {
			return m
		}
	}
	return ""
}

// skipAfter returns the heading level being skipped after l: a drop heading starts it, an equal or higher one ends it.
func skipAfter(base, l string, skip int) int {
	lvl := headingLevel(l)
	if lvl == 0 {
		return skip
	}
	if skip > 0 && lvl <= skip {
		skip = 0
	}
	for _, d := range externalDrops {
		if d.file == base && d.heading == l {
			skip = lvl
		}
	}
	return skip
}

func droppedLine(base, l string) bool {
	for _, d := range externalDrops {
		if d.file == base && d.linePrefix != "" && strings.HasPrefix(l, d.linePrefix) {
			return true
		}
	}
	return false
}

// headingLevel returns the ATX heading level of l, or 0 when l is not a heading.
func headingLevel(l string) int {
	n := len(l) - len(strings.TrimLeft(l, "#"))
	if n == 0 || n > 6 || len(l) == n || l[n] != ' ' {
		return 0
	}
	return n
}

type standard struct{ path, body string }

// unscopedStandards reads rules/standards/*.md without `paths:` frontmatter, sorted; a read failure names the file.
func unscopedStandards(root string) ([]standard, error) {
	files, err := filepath.Glob(filepath.Join(root, "rules", "standards", "*.md"))
	if err != nil {
		return nil, err
	}
	slices.Sort(files)
	var out []standard
	for _, f := range files {
		raw, err := os.ReadFile(f)
		if err != nil {
			return nil, fmt.Errorf("read standards %s: %w", f, err)
		}
		fm, body := textutil.ParseFrontmatter(string(raw))
		if fm["paths"] == nil {
			out = append(out, standard{f, body})
		}
	}
	return out, nil
}

// standardsSection renders the always-on rules/standards/*.md, H1s demoted.
func standardsSection(root string) (string, error) {
	standards, err := unscopedStandards(root)
	if err != nil || len(standards) == 0 {
		return "", err
	}
	var b strings.Builder
	for _, s := range standards {
		b.WriteByte('\n')
		b.WriteString(demoteH1(strings.Trim(dropForExternal(s.path, s.body), "\n")))
		b.WriteByte('\n')
	}
	return "\n## Standards\n" + b.String(), nil
}

// demoteH1 turns each `# ` heading outside a code fence into `## `.
func demoteH1(body string) string {
	lines := strings.Split(body, "\n")
	fenced := false
	for i, l := range lines {
		if strings.HasPrefix(l, "```") || strings.HasPrefix(l, "~~~") {
			fenced = !fenced
		} else if !fenced && strings.HasPrefix(l, "# ") {
			lines[i] = "#" + l
		}
	}
	return strings.Join(lines, "\n")
}

// renderDocs renders the banner, CLAUDE.md and always-on standards minus externalDrops.
func renderDocs(root string) (content string, ok bool, err error) {
	src, err := instructionSource(root)
	if err != nil {
		return "", false, nil
	}
	conventions, err := os.ReadFile(src)
	if err != nil {
		return "", false, fmt.Errorf("read %s: %w", filepath.Base(src), err)
	}
	standards, err := standardsSection(root)
	if err != nil {
		return "", false, err
	}
	conventions = []byte(dropForExternal(src, string(conventions)))
	var b strings.Builder
	b.WriteString(docsBanner + "\n\n" + docsPathsNote + "\n\n")
	b.WriteString(strings.TrimRight(string(conventions), "\n"))
	b.WriteByte('\n')
	b.WriteString(standards)
	return b.String(), true, nil
}
